const d = (slug, title, task, solution, hint, given = '') => ({ kind: 'drill', slug, title, task, solution, hint, given });
const M = (body) => `#include <stdio.h>\n\nint main(void) {\n${body}\n    return 0;\n}\n`;
const H = (body) => `#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n${body}\n    return 0;\n}\n`;

